package com.bank.helm.model;

// The values that fill the template blanks. Base + per-environment override.
public class ChartValues {
    private int replicaCount;
    private String imageTag;
    private String memoryLimit;

    public ChartValues(int replicaCount, String imageTag, String memoryLimit) {
        this.replicaCount = replicaCount;
        this.imageTag = imageTag;
        this.memoryLimit = memoryLimit;
    }

    public int getReplicaCount() { return replicaCount; }
    public String getImageTag() { return imageTag; }
    public String getMemoryLimit() { return memoryLimit; }

    // Merge: start from base, apply only the non-null fields of the override.
    public ChartValues mergeWith(ChartValues override) {
        return new ChartValues(
            override.replicaCount > 0 ? override.replicaCount : this.replicaCount,
            override.imageTag != null ? override.imageTag : this.imageTag,
            override.memoryLimit != null ? override.memoryLimit : this.memoryLimit
        );
    }
}
