package com.bank.helm.model;

// A numbered release revision — the unit Helm keeps in its history.
public class HelmRelease {
    private final int revision;
    private final String renderedManifest;
    private final ChartValues values;

    public HelmRelease(int revision, String renderedManifest, ChartValues values) {
        this.revision = revision;
        this.renderedManifest = renderedManifest;
        this.values = values;
    }

    public int getRevision() { return revision; }
    public String getRenderedManifest() { return renderedManifest; }
    public ChartValues getValues() { return values; }
}
