package com.bank.helm.release;

import com.bank.helm.model.*;
import java.util.*;
import java.util.logging.Logger;

// Models Helm: render a template with values, idempotent upgrade/install,
// revision history, and one-command rollback.
public class ReleaseManager {
    private static final Logger log = Logger.getLogger(ReleaseManager.class.getName());

    private final Map<String, List<HelmRelease>> history = new HashMap<>();

    // Render ONE template with the merged values — like Helm templating.
    public String render(ChartValues v) {
        return "Deployment payments-service replicas=" + v.getReplicaCount()
             + " image=bank/payments-service:" + v.getImageTag()
             + " memLimit=" + v.getMemoryLimit();
    }

    // upgrade --install: install if absent, upgrade if present. Idempotent.
    public HelmRelease upgradeOrInstall(String releaseName, ChartValues base, ChartValues override) {
        ChartValues merged = base.mergeWith(override);
        String manifest = render(merged);
        List<HelmRelease> revs = history.computeIfAbsent(releaseName, k -> new ArrayList<>());
        int nextRevision = revs.size() + 1;
        HelmRelease release = new HelmRelease(nextRevision, manifest, merged);
        revs.add(release);
        if (nextRevision == 1) log.info(() -> "INSTALL " + releaseName + " rev 1 → " + manifest);
        else log.info(() -> "UPGRADE " + releaseName + " rev " + nextRevision + " → " + manifest);
        return release;
    }

    // rollback: restore a previous revision as a NEW revision (Helm's model).
    public HelmRelease rollback(String releaseName, int targetRevision) {
        List<HelmRelease> revs = history.get(releaseName);
        if (revs == null || targetRevision < 1 || targetRevision > revs.size()) {
            throw new IllegalArgumentException("No revision " + targetRevision + " for " + releaseName);
        }
        HelmRelease target = revs.get(targetRevision - 1);
        int newRevision = revs.size() + 1;
        HelmRelease restored = new HelmRelease(newRevision, target.getRenderedManifest(), target.getValues());
        revs.add(restored);
        log.warning(() -> "ROLLBACK " + releaseName + " to rev " + targetRevision
                + " (recorded as rev " + newRevision + ") → " + target.getRenderedManifest());
        return restored;
    }

    public int currentRevision(String releaseName) {
        return history.getOrDefault(releaseName, List.of()).size();
    }
}
