package com.bank.helm;

import com.bank.helm.model.ChartValues;
import com.bank.helm.release.ReleaseManager;
import java.util.logging.*;

public class HelmDemoApplication {
    private static final Logger log = Logger.getLogger(HelmDemoApplication.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new HelmLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        ReleaseManager helm = new ReleaseManager();

        // Base values (values.yaml): 1 replica, tag v42, 512Mi.
        ChartValues base = new ChartValues(1, "v42", "512Mi");
        // No-op override for dev.
        ChartValues devOverride = new ChartValues(0, null, null);
        // Prod override (values-prod.yaml): 5 replicas, 2Gi — tag inherited from base.
        ChartValues prodOverride = new ChartValues(5, null, "2Gi");

        // SAME template, different environments — proves per-env values.
        helm.upgradeOrInstall("payments-dev", base, devOverride);
        helm.upgradeOrInstall("payments-prod", base, prodOverride);

        // Ship a new image to prod (upgrade, not install — same command).
        helm.upgradeOrInstall("payments-prod", new ChartValues(1, "v43", "512Mi"), prodOverride);

        // Ship a BAD image to prod.
        helm.upgradeOrInstall("payments-prod", new ChartValues(1, "v44-broken", "512Mi"), prodOverride);
        log.severe(() -> "payments-prod rev " + helm.currentRevision("payments-prod") + " is BROKEN");

        // One-command rollback to the last good revision (rev 2 = v43).
        helm.rollback("payments-prod", 2);
        log.info(() -> "payments-prod now at rev " + helm.currentRevision("payments-prod") + " (restored good config)");
    }
}

